hello:
/* @plugin {"id":"hello-plugin","name":"Hello plugin","version":"1.0.0","permissions":["commands"]} */
mentos.commands.add('hello', 'Say hello', (args) => {
  return args.trim() ? 'Hello, ' + args.trim() + '!' : 'Hello from Mentos!';
});

counter:
let count = mentos.storage.get('count', 0);
mentos.ui.page({
  id: 'main', title: 'My counter', icon: 'calculate',
  render: () => [
    { type: 'stat', label: 'Taps', value: String(count) },
    { type: 'button', label: 'Add one', onTap: () => {
      count++;
      mentos.storage.set('count', count);
    } },
  ],
});

slots:
mentos.ui.slot('feed.top', () => [
  { type: 'text', text: 'A small reminder for today.' },
]);
mentos.ui.tab({ title: 'Counter', icon: 'calculate', page: 'main' });

peers:
mentos.peers.on((message) => {
  mentos.log(message.name, message.data);
});
